using System.Diagnostics; using System.Runtime.Versioning; namespace MacChanger.Core; [SupportedOSPlatform("windows")] public sealed class WindowsCommandExecutor:IWindowsCommandExecutor { public async Task<OperationResult> ExecuteAsync(string command,CancellationToken ct=default){var log=Path.GetTempFileName();try{var script=$"{command} *> '{log.Replace("'","''")}'";var psi=new ProcessStartInfo("powershell.exe",$"-NoProfile -NonInteractive -Command \"{script}\""){UseShellExecute=true,Verb="runas",WindowStyle=ProcessWindowStyle.Hidden};using var p=Process.Start(psi);if(p is null)return new(false,"Could not start elevated PowerShell.");await p.WaitForExitAsync(ct);var t=File.Exists(log)?await File.ReadAllTextAsync(log,ct):"";return p.ExitCode==0?new(true,string.IsNullOrWhiteSpace(t)?"Command completed.":t.Trim()):new(false,string.IsNullOrWhiteSpace(t)?$"PowerShell exited with code {p.ExitCode}.":t.Trim());}catch(Exception ex){return new(false,ex.Message);}finally{try{File.Delete(log);}catch{}}} }
